import {ToolRegistry} from './registry.js';

describe('ToolRegistry numeric validation', () => {
  it('rejects NaN for a numeric temperature (specs/hal-engine-tool-input-validation/spec.md#11)', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'temperature',
        description: 'Report temperature',
        inputSchema: {type: 'object', properties: {temperature: {type: 'number'}}},
      },
      async () => {
        throw new Error('Invalid temperature reached the executor');
      },
    );

    const response = await registry.execute('temperature', {temperature: NaN});

    expect(response.result).toMatch(/temperature.*number/);
  });
});
